// Get staging and production workflow lists
const stagingItems = $input.first().json.data || [];
const prodItems = $input.last().json.data || [];

// Build lookup maps by workflow ID
const stagingMap = new Map();
stagingItems.forEach(w => stagingMap.set(w.id, w));

const prodMap = new Map();
prodItems.forEach(w => prodMap.set(w.id, w));

// Deep diff helper for two objects
function deepEqual(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

// Compare nodes between staging and production versions of a workflow
function diffNodes(stagingNodes, prodNodes) {
  const stagingByName = new Map();
  (stagingNodes || []).forEach(n => stagingByName.set(n.name, n));

  const prodByName = new Map();
  (prodNodes || []).forEach(n => prodByName.set(n.name, n));

  const added = [];
  const removed = [];
  const modified = [];

  for (const [name, sNode] of stagingByName) {
    if (!prodByName.has(name)) {
      added.push({ name, type: sNode.type });
    }
  }

  for (const [name, pNode] of prodByName) {
    if (!stagingByName.has(name)) {
      removed.push({ name, type: pNode.type });
    }
  }

  for (const [name, sNode] of stagingByName) {
    const pNode = prodByName.get(name);
    if (!pNode) continue;

    const changes = [];

    if (sNode.type !== pNode.type) {
      changes.push(`type: ${pNode.type} \u2192 ${sNode.type}`);
    }

    if (!deepEqual(sNode.parameters, pNode.parameters)) {
      const allKeys = new Set([
        ...Object.keys(sNode.parameters || {}),
        ...Object.keys(pNode.parameters || {})
      ]);
      const paramChanges = [];
      for (const key of allKeys) {
        const sVal = (sNode.parameters || {})[key];
        const pVal = (pNode.parameters || {})[key];
        if (!deepEqual(sVal, pVal)) {
          if (pVal === undefined) {
            paramChanges.push(`+${key}`);
          } else if (sVal === undefined) {
            paramChanges.push(`-${key}`);
          } else {
            const sStr = typeof sVal === 'string' ? sVal : JSON.stringify(sVal);
            const pStr = typeof pVal === 'string' ? pVal : JSON.stringify(pVal);
            if (sStr.length < 50 && pStr.length < 50) {
              paramChanges.push(`${key}: \`${pStr}\` \u2192 \`${sStr}\``);
            } else {
              paramChanges.push(`${key} (modified)`);
            }
          }
        }
      }
      if (paramChanges.length > 0) {
        changes.push(`params: ${paramChanges.join(', ')}`);
      }
    }

    if (changes.length > 0) {
      modified.push({ name, type: sNode.type, changes });
    }
  }

  return { added, removed, modified };
}

// Compare connections
function diffConnections(stagingConns, prodConns) {
  const sKeys = Object.keys(stagingConns || {});
  const pKeys = Object.keys(prodConns || {});

  const addedConns = sKeys.filter(k => !pKeys.includes(k));
  const removedConns = pKeys.filter(k => !sKeys.includes(k));
  const changedConns = [];

  for (const key of sKeys) {
    if (pKeys.includes(key) && !deepEqual(stagingConns[key], prodConns[key])) {
      changedConns.push(key);
    }
  }

  return { addedConns, removedConns, changedConns };
}

// Compare settings
function diffSettings(stagingSettings, prodSettings) {
  const s = stagingSettings || {};
  const p = prodSettings || {};
  const allKeys = new Set([...Object.keys(s), ...Object.keys(p)]);
  const changes = [];

  for (const key of allKeys) {
    if (!deepEqual(s[key], p[key])) {
      if (p[key] === undefined) {
        changes.push(`+${key}: \`${JSON.stringify(s[key])}\``);
      } else if (s[key] === undefined) {
        changes.push(`-${key}`);
      } else {
        changes.push(`${key}: \`${JSON.stringify(p[key])}\` \u2192 \`${JSON.stringify(s[key])}\``);
      }
    }
  }

  return changes;
}

// Classify each workflow
const inSync = [];
const drifted = [];
const newOnStaging = [];
const orphanedOnProd = [];

for (const [id, sw] of stagingMap) {
  const pw = prodMap.get(id);
  if (!pw) {
    newOnStaging.push({
      id: sw.id,
      name: sw.name,
      updatedAt: sw.updatedAt,
      active: sw.active,
      nodeCount: (sw.nodes || []).length,
      nodeTypes: [...new Set((sw.nodes || []).map(n => n.type.split('.').pop()))]
    });
  } else if (sw.versionId !== pw.versionId) {
    const nodeDiff = diffNodes(sw.nodes, pw.nodes);
    const connDiff = diffConnections(sw.connections, pw.connections);
    const settingsDiff = diffSettings(sw.settings, pw.settings);
    const activeChanged = sw.active !== pw.active;

    drifted.push({
      id: sw.id,
      name: sw.name,
      stagingUpdated: sw.updatedAt,
      prodUpdated: pw.updatedAt,
      stagingActive: sw.active,
      prodActive: pw.active,
      activeChanged,
      nodeDiff,
      connDiff,
      settingsDiff,
      stagingNodeCount: (sw.nodes || []).length,
      prodNodeCount: (pw.nodes || []).length
    });
  } else {
    inSync.push({ id: sw.id, name: sw.name, active: sw.active });
  }
}

for (const [id, pw] of prodMap) {
  if (!stagingMap.has(id)) {
    orphanedOnProd.push({
      id: pw.id,
      name: pw.name,
      updatedAt: pw.updatedAt,
      active: pw.active
    });
  }
}

// Build Slack message
const now = new Date().toISOString().split('T')[0];
let msg = `*Darwin Drift Report \u2014 ${now}*\n\n`;

msg += `*In sync:* ${inSync.length} workflow${inSync.length !== 1 ? 's' : ''}`;
if (inSync.length > 0) {
  msg += ` (${inSync.map(w => w.name).join(', ')})`;
}
msg += `\n\n`;

if (drifted.length > 0) {
  msg += `*Staged changes (not yet on production):*\n\n`;
  for (const d of drifted) {
    const stagingDate = new Date(d.stagingUpdated).toLocaleDateString('en-US', {month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'});
    msg += `*${d.name}* (\`${d.id}\`)\n`;
    msg += `  Staging updated: ${stagingDate} | Nodes: ${d.prodNodeCount} \u2192 ${d.stagingNodeCount}\n`;

    if (d.activeChanged) {
      msg += `  Active status: prod=${d.prodActive} \u2192 staging=${d.stagingActive}\n`;
    }

    const nd = d.nodeDiff;
    if (nd.added.length > 0) {
      msg += `  + Nodes added: ${nd.added.map(n => `${n.name} (${n.type.split('.').pop()})`).join(', ')}\n`;
    }
    if (nd.removed.length > 0) {
      msg += `  - Nodes removed: ${nd.removed.map(n => `${n.name} (${n.type.split('.').pop()})`).join(', ')}\n`;
    }
    if (nd.modified.length > 0) {
      msg += `  ~ Nodes modified:\n`;
      for (const m of nd.modified) {
        msg += `    \u2022 ${m.name}: ${m.changes.join('; ')}\n`;
      }
    }

    const cd = d.connDiff;
    if (cd.addedConns.length > 0 || cd.removedConns.length > 0 || cd.changedConns.length > 0) {
      const connParts = [];
      if (cd.addedConns.length > 0) connParts.push(`+${cd.addedConns.length} new`);
      if (cd.removedConns.length > 0) connParts.push(`-${cd.removedConns.length} removed`);
      if (cd.changedConns.length > 0) connParts.push(`${cd.changedConns.length} rewired`);
      msg += `  Connections: ${connParts.join(', ')}\n`;
    }

    if (d.settingsDiff.length > 0) {
      msg += `  Settings: ${d.settingsDiff.join('; ')}\n`;
    }

    msg += `\n`;
  }
}

if (newOnStaging.length > 0) {
  msg += `*New on staging (never deployed):*\n`;
  for (const n of newOnStaging) {
    const created = new Date(n.updatedAt).toLocaleDateString('en-US', {month: 'short', day: 'numeric'});
    msg += `\u2022 *${n.name}* (\`${n.id}\`) \u2014 ${n.nodeCount} nodes (${n.nodeTypes.join(', ')}), created ${created}, active: ${n.active}\n`;
  }
  msg += `\n`;
}

if (orphanedOnProd.length > 0) {
  msg += `*Orphaned on production (not on staging):*\n`;
  for (const o of orphanedOnProd) {
    const updated = new Date(o.updatedAt).toLocaleDateString('en-US', {month: 'short', day: 'numeric'});
    msg += `\u2022 *${o.name}* (\`${o.id}\`) \u2014 last updated ${updated}, active: ${o.active}\n`;
  }
  msg += `\n`;
}

if (drifted.length === 0 && newOnStaging.length === 0 && orphanedOnProd.length === 0) {
  msg += `Everything is in sync! No deployment needed.\n\n`;
}

msg += `---\n_Total: ${stagingMap.size} staging, ${prodMap.size} production | ${drifted.length} drifted, ${newOnStaging.length} new, ${orphanedOnProd.length} orphaned_`;

msg += `\n\ncc <@U07S2V7RH6K>`;

return [{ json: { text: msg, channel: 'C09DRCJLQCE', inSyncCount: inSync.length, driftedCount: drifted.length, newCount: newOnStaging.length, orphanedCount: orphanedOnProd.length } }];
